    contacts = []
    for _ in range(n):
        contacts.append(input().strip())

    results = []

    for i in range(n):
        target = contacts[i]
        best_sequence = None

        # Try all possible substrings of target (non-empty)
        # We will check if any substring appears only in this number
        # We can use a greedy approach: try shorter substrings first
        # Since we need the shortest sequence that matches only this number,
        # we can generate all substrings and check which one appears only in this number

        for length in range(1, 10):
            for start in range(10 - length):
                substring = target[start:start + length]
                matches = []
                for j in range(n):
                    if substring in contacts[j]:
                        matches.append(j)

                # If this substring appears only in the current number (i)
                if len(matches) == 1 and matches[0] == i:
                    best_sequence = substring
                    break

            if best_sequence:
                break

        results.append(best_sequence)

    for res in results:
        print(res)

